WITH base AS (SELECT id, customer_id, balance, opened_date, status, CONCAT_WS('/', status, account_type) AS status_account_type_key FROM accounts WHERE opened_date < '2023-07-01') SELECT status, SIZE(COLLECT_SET(status)) AS num_status, ROUND(AVG(balance), 2) AS avg_balance, APPROX_PERCENTILE(balance, ARRAY(0.25, 0.5, 0.75)) AS balance_quartiles, SORT_ARRAY(COLLECT_SET(status)) AS status_list FROM base GROUP BY status ORDER BY status DESC;
